import{_ as s,o as t,c as a,ag as i}from"./chunks/framework.DMVuHR7L.js";const g=JSON.parse('{"title":"Screenshot pipeline (for agents)","description":"","frontmatter":{},"headers":[],"relativePath":"bots/screenshots.md","filePath":"bots/screenshots.md","lastUpdated":1780006408000}'),n={name:"bots/screenshots.md"};function h(o,e,r,l,d,p){return t(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="screenshot-pipeline-for-agents" tabindex="-1">Screenshot pipeline (for agents) <a class="header-anchor" href="#screenshot-pipeline-for-agents" aria-label="Permalink to &quot;Screenshot pipeline (for agents)&quot;">​</a></h1><p>WebLogcat ships with a Playwright script that drives the <a href="./../features/simulator">simulator</a> and writes PNGs that both the docs site and the README depend on. Use it whenever:</p><ul><li>A UI change makes one of the existing screenshots look wrong.</li><li>A new widget / feature needs a hero shot.</li><li>The user asks you to refresh the README screenshot or any docs imagery.</li></ul><h2 id="where-the-script-lives" tabindex="-1">Where the script lives <a class="header-anchor" href="#where-the-script-lives" aria-label="Permalink to &quot;Where the script lives&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>scripts/capture-feature-screenshots.spec.ts   # the captures</span></span>
<span class="line"><span>playwright.screenshots.config.ts              # standalone playwright config</span></span></code></pre></div><p>The script is <strong>not</strong> part of <code>npm run e2e</code> — it&#39;s invoked explicitly via <code>npm run docs:screenshots</code> so a flaky capture never blocks merges and a UI change can land without a forced regen.</p><h2 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h2><p>Every shot is captured <strong>twice</strong> — once in dark mode, once in light. The dark variant lands at the canonical filename; the light variant is suffixed with <code>-light</code>.</p><table tabindex="0"><thead><tr><th>Output path</th><th>Used by</th></tr></thead><tbody><tr><td><code>docs/public/img/features/&lt;slug&gt;.png</code></td><td><code>&lt;ThemeImage src-dark=&quot;...&quot;&gt;</code> in the matching <code>docs/features/&lt;slug&gt;.md</code> page (dark theme)</td></tr><tr><td><code>docs/public/img/features/&lt;slug&gt;-light.png</code></td><td><code>&lt;ThemeImage src-light=&quot;...&quot;&gt;</code> in the same page (light theme)</td></tr><tr><td><code>docs/public/screenshot.png</code></td><td>README hero image <strong>and</strong> the docs <code>image.dark</code> hero (single source of truth)</td></tr><tr><td><code>docs/public/screenshot-light.png</code></td><td>The docs <code>image.light</code> hero — VitePress swaps to it when the reader toggles light mode</td></tr></tbody></table><p>The dual-theme capture exists so feature pages render coherently for readers regardless of which appearance they pick. Don&#39;t ship one variant without the other; reviewers will bounce single-theme PRs.</p><h2 id="refreshing-screenshots" tabindex="-1">Refreshing screenshots <a class="header-anchor" href="#refreshing-screenshots" aria-label="Permalink to &quot;Refreshing screenshots&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. Build the app so the preview server has fresh dist/.</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. Run the capture (uses vite preview at localhost:4173).</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span></span></code></pre></div><p>In environments where Playwright cannot fetch its pinned Chromium build, point at any preinstalled Chromium 1194+ binary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHROMIUM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/opt/pw-browsers/chromium-1194/chrome-linux/chrome</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:screenshots</span></span></code></pre></div><p>The script:</p><ol><li>Boots <code>vite preview</code> on port 4173.</li><li>For each <code>(feature, theme)</code> pair (the script wraps every feature capture in a <code>for theme of [&#39;dark&#39;, &#39;light&#39;]</code> loop), seeds <code>localStorage</code> with <code>theme: &lt;theme&gt;</code> + <code>accent: &#39;indigo&#39;</code> + <code>performanceMode: &#39;on&#39;</code>, then loads the app and clicks <strong>fake data</strong> to drop into the simulator.</li><li>Asserts <code>&lt;html data-theme=&lt;theme&gt;&gt;</code> so the page actually rendered in the requested theme before snapshotting (Playwright&#39;s <code>addInitScript</code> runs before page scripts; if the seed didn&#39;t stick, this assertion catches it).</li><li>Writes the PNG to <code>docs/public/img/features/&lt;slug&gt;.png</code> (dark) or <code>…/&lt;slug&gt;-light.png</code> (light).</li></ol><p>After it runs, <strong>review every changed PNG</strong> in <em>both</em> themes — open each pair and confirm:</p><ul><li>The right widget rendered.</li><li>No error overlay, no clipped content, no console-error toast bleeding through.</li><li>The light variant actually reads as light (the dashboard&#39;s light theme has rough edges in some chrome — see <a href="./test-sync">test-sync</a> if you find a regression worth fixing in the app itself rather than the docs).</li></ul><p>The script asserts that the canonical DOM elements rendered, but it can&#39;t tell you whether the composition is aesthetically right.</p><h2 id="refreshing-only-the-hero" tabindex="-1">Refreshing only the hero <a class="header-anchor" href="#refreshing-only-the-hero" aria-label="Permalink to &quot;Refreshing only the hero&quot;">​</a></h2><p>The hero comes out of a dedicated <code>hero shot</code> capture that seeds <code>localStorage</code> with a deterministic four-widget composition before navigating, so the shot is bit-stable across regens. Two variants ship — <code>screenshot.png</code> (dark) and <code>screenshot-light.png</code> (light).</p><p>The seeded state:</p><ul><li><strong>Tweaks</strong> — <code>theme: &lt;dark|light&gt;</code>, <code>accent: &#39;indigo&#39;</code> (matches the docs site&#39;s brand at hue 268), <code>compactMode: true</code>, <code>performanceMode: &#39;on&#39;</code>.</li><li><strong>Layout</strong> — Mirror left (≈32% width), then a column split on the right with Logcat on top (≈62% height) and Shell | Dumpsys at the bottom (50/50).</li><li><strong>Simulator hints</strong> — same convention as the feature shots: the &quot;Using simulated log data&quot; toast is waited out and the &quot;Simulated log stream&quot; badge is hidden via an injected <code>display:none</code> rule before the screenshot fires. Readers shouldn&#39;t mistake those onboarding affordances for product chrome.</li></ul><p>Re-run only the heroes without churning the other PNGs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHROMIUM_PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">...</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> playwright</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --config=playwright.screenshots.config.ts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;hero shot&#39;</span></span></code></pre></div><p>It writes both variants. If the user asks specifically for <em>the README screenshot</em>, both files are in scope — the same composition is used for the docs landing.</p><p>To change the composition (different widgets, different ratios, a different accent), edit the <code>localStorage.setItem</code> block in <code>scripts/capture-feature-screenshots.spec.ts</code> under the <code>hero shot</code> test. Layout payload shape lives in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/layout.ts" target="_blank" rel="noreferrer"><code>src/lib/layout.ts</code></a> (<code>weblogcat-dashboard-v2</code>); tweak shape lives in <a href="https://github.com/gabrielhuff/web-logcat/blob/main/src/lib/tweaks.ts" target="_blank" rel="noreferrer"><code>src/lib/tweaks.ts</code></a> (<code>weblogcat:tweaks:v1</code>).</p><h2 id="authoring-a-feature-page" tabindex="-1">Authoring a feature page <a class="header-anchor" href="#authoring-a-feature-page" aria-label="Permalink to &quot;Authoring a feature page&quot;">​</a></h2><p>Reference both variants via the global <code>&lt;ThemeImage&gt;</code> Vue component (registered by <code>docs/.vitepress/theme/index.ts</code>):</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;ThemeImage</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  src-dark=&quot;/img/features/&lt;slug&gt;.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  src-light=&quot;/img/features/&lt;slug&gt;-light.png&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  alt=&quot;...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>The component reads <code>useData().isDark</code> and renders the right variant; both src paths are absolute paths into <code>docs/public/</code>, piped through <code>withBase()</code> so the rendered href is correct under production / staging / local-dev base paths. Don&#39;t reach for the plain markdown <code>![](./img/...)</code> syntax — the docs site&#39;s convention is dual-theme.</p><h2 id="adding-a-new-capture" tabindex="-1">Adding a new capture <a class="header-anchor" href="#adding-a-new-capture" aria-label="Permalink to &quot;Adding a new capture&quot;">​</a></h2><p>Add a <code>test(&#39;&lt;short description&gt;&#39;, …)</code> block <strong>inside</strong> the existing <code>for (const theme of [&#39;dark&#39;, &#39;light&#39;])</code> describe loop in <code>scripts/capture-feature-screenshots.spec.ts</code>. The harness then captures it for both themes automatically. The pattern:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">test</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my new capture&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ({ </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">page</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bootSimulator</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(page, theme);</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // …drive the widget to the state you want to capture;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // **wait on a DOM signal** that proves the state arrived</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // (don&#39;t \`setTimeout\` — it&#39;ll flake).</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tile.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">screenshot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ path: </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">out</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(theme, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-new-slug&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) });</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>Then reference both PNGs from the matching <code>docs/features/&lt;page&gt;.md</code> via <code>&lt;ThemeImage&gt;</code>.</p><h2 id="real-device-only-flows" tabindex="-1">Real-device-only flows <a class="header-anchor" href="#real-device-only-flows" aria-label="Permalink to &quot;Real-device-only flows&quot;">​</a></h2><p>These cannot be captured by the script:</p><ul><li>Mirror&#39;s live screen frame — the simulator shows a static placeholder.</li><li>Files transfers (drag-out / drag-in) — no-ops in the simulator.</li><li>The WebUSB pairing dialog — Chromium chrome, not part of the page.</li></ul><p>For these, capture manually against a real device and commit the PNG pair (one per theme) under <code>docs/public/img/features/</code>. Flag the source in the alt-text so a future regen doesn&#39;t quietly replace it.</p>`,39)])])}const k=s(n,[["render",h]]);export{g as __pageData,k as default};
